<section class="p-section"><h2>Add a student record</h2><p class="p-muted">Existing student identities are reused by email. New records remain pending review and do not create paid enrollments.</p><form class="p-form" method="post" action="<?= base_url('/partner/students') ?>"><?= csrf_field() ?><label>Full name<input name="name" required maxlength="150"></label><label>Email<input type="email" name="email" required maxlength="190"></label><label>Mobile number<input name="phone" maxlength="30"></label><label>TCM One course<select name="course_id"><option value="">Select if applicable</option><?php foreach($courses as $c): ?><option value="<?= (int)$c['id'] ?>"><?= e($c['title']) ?></option><?php endforeach ?></select></label><label>Proposed batch<select name="batch_id"><option value="">No batch</option><?php foreach($batches as $b): ?><option value="<?= (int)$b['id'] ?>"><?= e($b['batch_name']) ?></option><?php endforeach ?></select></label><label class="wide"><span><input type="checkbox" name="consent" value="1"> Student/guardian consent to share these details with TCM One has been obtained.</span></label><div class="wide"><button class="tcm-btn primary" type="submit">Submit Student Record</button></div></form></section>
<section class="p-section"><h2>Student records</h2><?php if(!$rows): ?><div class="p-empty">No student records yet.</div><?php else: ?><div class="p-table-wrap"><table class="p-table"><thead><tr><th>Student</th><th>Course / Batch</th><th>Admission Date</th><th>Review Status</th><th>Consent</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['name']) ?><br><span class="p-muted"><?= e($r['email']) ?> <?= e($r['phone']??'') ?></span></td><td><?= e($r['course_title']??'—') ?><br><?= e($r['batch_name']??'') ?></td><td><?= e(date('d M Y',strtotime($r['created_at']))) ?></td><td><span class="p-pill"><?= e(str_replace('_',' ',$r['status'])) ?></span></td><td><?= $r['consent_at']?'Recorded':'Not recorded' ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section>
